def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([0]), fmt([5]), fmt([0, 0, 0]), fmt([10, 2]), fmt([3, 30, 34, 5, 9]), fmt([1, 1, 1]),
             fmt([121, 12]), fmt([0, 1]), fmt([0, 0, 1]), fmt([10, 100, 1000]), fmt([824, 8247]), fmt([432, 43243]),
             fmt([10 ** 9, 10 ** 9 - 1, 999999999, 9])]
    pool = [3, 30, 34, 303, 330, 33, 9, 98, 989, 1, 10, 100, 0]
    for _ in range(14):
        n = rng.randint(2, 7)
        if rng.random() < 0.5:
            tests.append(fmt([rng.choice(pool) for _ in range(n)]))
        else:
            tests.append(fmt([rng.randint(0, 120) for _ in range(n)]))
    n = 20000
    tests.append(fmt([rng.randint(0, 10 ** 9) for _ in range(n)]))
    bases = ['3', '34', '30', '342', '9', '98', '989', '1', '12', '121']
    tests.append(fmt([int(rng.choice(bases) * rng.randint(1, 3)) for _ in range(n)]))
    tests.append(fmt([0] * (n - 3) + [10 ** 9, 0, 7]))
    tests.append(fmt([10 ** 9] * n))
    return tests
